<?php
declare(strict_types=1);
namespace BSPCompare;
require_once dirname(__DIR__,2).'/research/_lib/model.php';
const VERSION='1.6.0';const ROOT='/model-comparison/';const SCHEMA='beyondspacetime.sweep-plan.v1';
function presets():array{return [
 'light'=>['title'=>'Energy loss and group speed','description'=>'Compare positive-gap drag with the zero-gap control at each identical drag rate.','model'=>'foundation:light-slowing','parameter'=>'drag','start'=>0,'end'=>2,'samples'=>21,'candidate'=>['gap'=>.2],'reference'=>['gap'=>0],'metric'=>'Final group speed / C'],
 'clocks'=>['title'=>'Physical clock prediction versus SR','description'=>'Compare a stipulated candidate clock rate with the SR count at the same reference rate, speed and duration. The two predictions are distinct outputs of one solver.','model'=>'foundation:constant-time','parameter'=>'beta','start'=>0,'end'=>.99,'samples'=>21,'candidate'=>['ratio'=>.8],'reference'=>['ratio'=>.8],'metric'=>'Candidate counts','reference_metric'=>'SR counts'],
 'escape'=>['title'=>'Escape versus reversible conversion','description'=>'Sweep escape strength, keeping the zero-escape comparator fixed at the same duration. Compare terminal total conversion, not individual photon slowing.','model'=>'evidence:escape','parameter'=>'ratio','start'=>0,'end'=>16,'samples'=>33,'candidate'=>[],'reference'=>['ratio'=>0],'metric'=>'Final total converted'],
 'wall'=>['title'=>'Competing drag bounds','description'=>'Compare the entry-monotonicity lower bound with the strict crossing upper bound for the same wall assumptions. Positive difference is a conflict, not a feasible interval.','model'=>'evidence:wall','parameter'=>'ceiling','start'=>1.001,'end'=>2,'samples'=>31,'candidate'=>['loggap'=>-1],'reference'=>['loggap'=>-1],'metric'=>'Minimum entry-monotone drag','reference_metric'=>'Strict upper drag for crossing'],
 'distance'=>['title'=>'Signed astronomical inference bias','description'=>'Compare inferred distance with the calibrated geometric input under the same extinction offset. This does not establish a universal correction.','model'=>'foundation:distance-inference','parameter'=>'extinction','start'=>-1,'end'=>3,'samples'=>21,'candidate'=>[],'reference'=>[],'metric'=>'Inferred distance','reference_metric'=>'Calibrated distance'],
 'age'=>['title'=>'Conventional expansion-age sensitivity','description'=>'Compare two flat matter–Λ reference histories with differing matter fractions. This is not a comparison of a parent cosmos with observed cosmology.','model'=>'foundation:cosmic-age','parameter'=>'h0','start'=>45,'end'=>95,'samples'=>21,'candidate'=>['matter'=>.3],'reference'=>['matter'=>.4],'metric'=>'Modeled age'],
 'anchors'=>['title'=>'Geometric anchor sensitivity','description'=>'Compare proposed downward distance shifts with unchanged LMC calibration. Quoted combined uncertainty is not a new likelihood or a detection.','model'=>'evidence:anchors','parameter'=>'percent','start'=>0,'end'=>30,'samples'=>31,'candidate'=>[],'reference'=>['percent'=>0],'metric'=>'LMC shift / combined uncertainty']
 ];}
function preset(string $id):array{$p=presets()[$id]??throw new \InvalidArgumentException('Unknown preset.');$p['schema']=SCHEMA;$p['reference_mode']=in_array($id,['escape','anchors'],true)?'fixed':'matched';$p['reference_metric']=$p['reference_metric']??$p['metric'];return $p;}
function run_model(string $id,array $p):array{$m=\BSPResearch\models()[$id];return $m['kind']==='foundation'?\solve($m['id'],$p):\calc($m['id'],$p);}
function normalized_params(string $id,array $p):array{$q=\BSPResearch\normalize(['schema'=>\BSPResearch\SCHEMA,'title'=>'Sweep','question'=>'Parameter sensitivity','cases'=>[['label'=>'Case','model'=>$id,'parameters'=>$p]],'evidence'=>[]]);return $q['cases'][0]['parameters'];}
function numeric_metric(array $r,string $label):array{foreach($r['metrics'] as $m)if($m['label']===$label&&(is_float($m['value'])||is_int($m['value']))&&is_finite((float)$m['value']))return $m;throw new \InvalidArgumentException('Unknown or nonnumeric metric: '.$label);}
function pairs():array{return ['foundation:constant-time'=>[['Candidate counts','SR counts']], 'evidence:wall'=>[['Minimum entry-monotone drag','Strict upper drag for crossing']], 'foundation:distance-inference'=>[['Inferred distance','Calibrated distance']]];}
function normalize(array $p):array{\BSPResearch\keys($p,['schema','title','description','model','parameter','start','end','samples','candidate','reference','metric','reference_metric','reference_mode','probe','half_width'],'sweep');if(($p['schema']??null)!==SCHEMA)throw new \InvalidArgumentException('Unsupported sweep schema.');$id=$p['model']??null;$models=\BSPResearch\models();if(!is_string($id)||!isset($models[$id]))throw new \InvalidArgumentException('Unknown model.');$ps=array_column($models[$id]['params'],null,'key');$key=$p['parameter']??null;if(!is_string($key)||!isset($ps[$key]))throw new \InvalidArgumentException('Unknown sweep parameter.');$bound=$ps[$key];foreach(['start','end'] as $k){$n=$p[$k]??null;if((!is_int($n)&&!is_float($n))||!is_finite((float)$n)||$n<$bound['min']||$n>$bound['max'])throw new \InvalidArgumentException('Invalid sweep '.$k.'.');}if($p['start']>=$p['end'])throw new \InvalidArgumentException('Sweep start must be below end.');$n=$p['samples']??null;if(!is_int($n)||$n<3||$n>65)throw new \InvalidArgumentException('Choose 3–65 samples.');$a=normalized_params($id,\BSPResearch\object($p['candidate']??[],'Candidate'));$b=normalized_params($id,\BSPResearch\object($p['reference']??[],'Reference'));$metric=$p['metric']??null;$ref=$p['reference_metric']??$metric;if(!is_string($metric)||!is_string($ref)||strlen($metric)>160||strlen($ref)>160)throw new \InvalidArgumentException('Choose a numeric metric.');if($metric!==$ref&&!in_array([$metric,$ref],pairs()[$id]??[],true))throw new \InvalidArgumentException('Different metrics may only be compared in an explicitly defined observable pair.');$mode=$p['reference_mode']??'matched';if(!in_array($mode,['matched','fixed'],true))throw new \InvalidArgumentException('Invalid reference mode.');if($metric!==$ref&&($mode!=='matched'||array_diff_assoc($a,$b)))throw new \InvalidArgumentException('Paired metrics require identical parameters and matched sweep.');$probe=$p['probe']??(($p['start']+$p['end'])/2);$width=$p['half_width']??(($p['end']-$p['start'])/10);foreach([$probe,$width] as $v)if((!is_int($v)&&!is_float($v))||!is_finite((float)$v))throw new \InvalidArgumentException('Invalid sensitivity probe.');if($probe<$p['start']||$probe>$p['end']||$width<0||$width>$p['end']-$p['start'])throw new \InvalidArgumentException('Probe or half-width outside sweep.');return ['schema'=>SCHEMA,'title'=>\BSPResearch\words($p['title']??'Scientific parameter sweep',160,'Title'),'description'=>\BSPResearch\words($p['description']??'Conditional model comparison.',600,'Description'),'model'=>$id,'parameter'=>$key,'start'=>(float)$p['start'],'end'=>(float)$p['end'],'samples'=>$n,'candidate'=>$a,'reference'=>$b,'metric'=>$metric,'reference_metric'=>$ref,'reference_mode'=>$mode,'probe'=>(float)$probe,'half_width'=>(float)$width];}
function evaluate(array $p):array{$p=normalize($p);$key=$p['parameter'];$id=$p['model'];$fixed=$p['reference_mode']==='fixed'?numeric_metric(run_model($id,$p['reference']),$p['reference_metric']):null;$at=function(float $x)use($p,$key,$id,$fixed){$a=$p['candidate'];$a[$key]=$x;$b=$p['reference'];$b[$key]=$x;$m=numeric_metric(run_model($id,$a),$p['metric']);$n=$fixed??numeric_metric(run_model($id,$b),$p['reference_metric']);if($m['unit']!==$n['unit'])throw new \InvalidArgumentException('Metric units differ.');$d=$m['value']-$n['value'];if(!is_finite($d))throw new \RuntimeException('Nonfinite difference');return ['x'=>$x,'candidate'=>$m['value'],'reference'=>$n['value'],'delta'=>$d,'unit'=>$m['unit']];};$rows=[];for($i=0;$i<$p['samples'];$i++)$rows[]=$at($i===$p['samples']-1?$p['end']:$p['start']+($p['end']-$p['start'])*$i/($p['samples']-1));$lo=max($p['start'],$p['probe']-$p['half_width']);$hi=min($p['end'],$p['probe']+$p['half_width']);$probes=[$at($lo),$at($p['probe']),$at($hi)];$slopes=[];foreach(['candidate','reference','delta'] as $k)$slopes[$k]=$hi>$lo?($probes[2][$k]-$probes[0][$k])/($hi-$lo):null;$m=\BSPResearch\models()[$id];$e=[];foreach($m['evidence'] as $rid)$e[]=\records()[$rid]+['url'=>'https://beyondspacetime.org/evidence/ledger/'.$rid.'/'];$sourceResult=run_model($id,$p['candidate']);$prov=\BSPResearch\provenance();$prov['comparison_version']=VERSION;$prov['source_files_sha256']['model-comparison/_lib/model.php']=hash_file('sha256',__FILE__);$r=['schema'=>'beyondspacetime.sweep-result.v1','plan'=>$p,'plan_sha256'=>hash('sha256',\BSPResearch\encode($p)),'parameter_label'=>array_column($m['params'],null,'key')[$key]['label'],'unit'=>$rows[0]['unit'],'parameter_unit'=>array_column($m['params'],null,'key')[$key]['unit'],'model_limitation'=>$sourceResult['limitation'],'source'=>$sourceResult['source'],'equation'=>$sourceResult['equation']??null,'rows'=>$rows,'probe'=>['lower'=>$probes[0],'center'=>$probes[1],'upper'=>$probes[2],'secant_slopes'=>$slopes,'clipped'=>$lo>$p['probe']-$p['half_width']||$hi<$p['probe']+$p['half_width']],'evidence'=>$e,'model_url'=>$m['url'],'provenance'=>$prov,'interpretation'=>'Conditional one-parameter sweep. Differences are candidate minus reference, using the same model and explicitly defined metric pairs only. Endpoint sensitivity is not a confidence interval, uncertainty propagation, optimization, likelihood or observational fit. No validation gate is passed.'];$r['result_sha256']=hash('sha256',\BSPResearch\encode($r));return $r;}
function catalog():array{$m=[];foreach(\BSPResearch\models() as $id=>$s){$r=run_model($id,normalized_params($id,[]));$m[$id]=$s+['numeric_metrics'=>array_values(array_filter($r['metrics'],fn($v)=>is_int($v['value'])||is_float($v['value']))),'allowed_pairs'=>pairs()[$id]??[]];}$p=[];foreach(presets() as $id=>$v)$p[$id]=preset($id);return ['version'=>VERSION,'schema'=>SCHEMA,'models'=>$m,'presets'=>$p,'max_samples'=>65,'endpoint'=>ROOT.'api/'];}
